     9	import { PropertiesQuery } from './properties.query';
    10	import {
    11	  isFiltering,
    12	  NO_FILTER,
    13	  PropertyFilters,
    14	  toPropertyFilter,
    15	  type FilterValues,
    16	} from './property-filters';
    17	
    18	type Property = PropertiesResult['properties'][number];
    19	
    20	const SORT_LABEL: Record<SortDirection, string> = {
