    29	
    30	/** S1 list with the S2 sort toggle and S3 filters. */
    31	export function PropertyList() {
    32	  const [direction, setDirection] = useState<SortDirection>(SortDirection.DESC);
    33	  const [filter, setFilter] = useState<FilterValues>(NO_FILTER);
    34	  const { data, error, loading, refetch } = useQuery(PropertiesQuery, {
    35	    variables: { filter: toPropertyFilter(filter), orderBy: { createdAt: direction } },
    36	    // The list is unmounted while a property is created, so a named refetch would miss it.
    37	    // Showing the cache and re-fetching on every mount keeps it current (S5.8).
