     1	import { useState, type FormEvent } from 'react';
     2	import { Button } from '@/components/ui/button';
     3	import { Input } from '@/components/ui/input';
     4	import { Label } from '@/components/ui/label';
     5	import { NativeSelect, NativeSelectOption } from '@/components/ui/native-select';
     6	import { USState, type PropertyFilter } from '@/gql/graphql';
     7	
     8	const STATES = Object.values(USState);
     9	
    10	export interface FilterValues {
    11	  city: string;
    12	  zipCode: string;
    13	  state: string;
    14	}
    15	
    16	export const NO_FILTER: FilterValues = { city: '', zipCode: '', state: '' };
    17	
    18	/** Blank fields mean "any" (S3.4); the server trims and validates again. */
    19	export function toPropertyFilter({ city, zipCode, state }: FilterValues): PropertyFilter {
    20	  return {
    21	    city: city.trim() || null,
    22	    zipCode: zipCode.trim() || null,
    23	    state: (state as USState) || null,
    24	  };
    25	}
    26	
    27	export const isFiltering = (values: FilterValues) =>
    28	  Object.values(toPropertyFilter(values)).some((value) => value !== null);
    29	
    30	/** S3 — filters apply on submit, so a half-typed zip never reaches the API. */
    31	export function PropertyFilters({
    32	  applied,
    33	  onApply,
    34	}: {
    35	  applied: FilterValues;
    36	  onApply: (values: FilterValues) => void;
    37	}) {
    38	  const [draft, setDraft] = useState(applied);
    39	  const [zipError, setZipError] = useState<string>();
    40	  const [prevApplied, setPrevApplied] = useState(applied);
    41	
    42	  // Keep the inputs in sync when filters are cleared from outside (e.g. the "no matches" state).
    43	  if (applied !== prevApplied) {
    44	    setPrevApplied(applied);
    45	    setDraft(applied);
    46	    setZipError(undefined);
    47	  }
    48	
    49	  const update = (field: keyof FilterValues) => (value: string) =>
    50	    setDraft((current) => ({ ...current, [field]: value }));
    51	
    52	  function onSubmit(event: FormEvent<HTMLFormElement>) {
    53	    event.preventDefault();
    54	    const zip = draft.zipCode.trim();
    55	    if (zip && !/^\d{5}$/.test(zip)) {
    56	      setZipError('Zip code must be exactly 5 digits.');
    57	      return;
    58	    }
    59	    setZipError(undefined);
    60	    onApply(draft);
    61	  }
    62	
    63	  return (
    64	    <form
    65	      onSubmit={onSubmit}
    66	      noValidate
    67	      aria-label="Filter properties"
    68	      className="grid gap-3 rounded-xl p-4 ring-1 ring-foreground/10 sm:grid-cols-[2fr_1fr_1fr_auto] sm:items-start"
    69	    >
    70	      <div className="grid gap-1.5">
    71	        <Label htmlFor="filter-city">City</Label>
    72	        <Input
    73	          id="filter-city"
    74	          value={draft.city}
    75	          onChange={(e) => update('city')(e.target.value)}
    76	          placeholder="Any city"
    77	        />
    78	      </div>
    79	      <div className="grid gap-1.5">
    80	        <Label htmlFor="filter-zip">Zip code</Label>
    81	        <Input
    82	          id="filter-zip"
    83	          value={draft.zipCode}
    84	          onChange={(e) => update('zipCode')(e.target.value)}
    85	          placeholder="Any"
    86	          inputMode="numeric"
    87	          maxLength={5}
    88	          aria-invalid={!!zipError}
    89	          aria-describedby={zipError ? 'filter-zip-error' : undefined}
    90	        />
    91	        {zipError && (
    92	          <p id="filter-zip-error" className="text-sm text-destructive">
    93	            {zipError}
    94	          </p>
    95	        )}
    96	      </div>
    97	      <div className="grid gap-1.5">
    98	        <Label htmlFor="filter-state">State</Label>
    99	        <NativeSelect
   100	          id="filter-state"
   101	          value={draft.state}
   102	          onChange={(e) => update('state')(e.target.value)}
   103	          className="w-full"
   104	        >
   105	          <NativeSelectOption value="">Any</NativeSelectOption>
   106	          {STATES.map((state) => (
   107	            <NativeSelectOption key={state} value={state}>
   108	              {state}
   109	            </NativeSelectOption>
   110	          ))}
   111	        </NativeSelect>
   112	      </div>
   113	      <div className="flex gap-2 sm:pt-[1.375rem]">
   114	        <Button type="submit">Apply</Button>
   115	        <Button
   116	          type="button"
   117	          variant="ghost"
   118	          onClick={() => onApply(NO_FILTER)}
   119	          disabled={!isFiltering(applied) && !isFiltering(draft)}
   120	        >
   121	          Clear
   122	        </Button>
   123	      </div>
   124	    </form>
   125	  );
   126	}
