     1	import { useState, type FormEvent } from 'react';
     2	import { useMutation } from '@apollo/client/react';
     3	import { Link, useNavigate } from 'react-router';
     4	import { CloudOff } from 'lucide-react';
     5	import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
     6	import { Button } from '@/components/ui/button';
     7	import { Input } from '@/components/ui/input';
     8	import { Label } from '@/components/ui/label';
     9	import { NativeSelect, NativeSelectOption } from '@/components/ui/native-select';
    10	import { USState } from '@/gql/graphql';
    11	import { CreatePropertyMutation } from './create-property.mutation';
    12	import {
    13	  validateProperty,
    14	  type PropertyFormErrors,
    15	  type PropertyFormValues,
    16	} from './validate-property';
    17	
    18	const STATES = Object.values(USState);
    19	const EMPTY: PropertyFormValues = { street: '', city: '', state: '', zipCode: '' };
    20	
    21	type Notice =
    22	  | { kind: 'weather'; message: string }
    23	  | { kind: 'duplicate'; message: string; existingPropertyId: string }
    24	  | { kind: 'error'; message: string };
    25	
    26	/** S5.8 — create a property; every CreatePropertyResult member has a visible outcome. */
    27	export function CreatePropertyForm() {
    28	  const navigate = useNavigate();
    29	  const [values, setValues] = useState(EMPTY);
    30	  const [errors, setErrors] = useState<PropertyFormErrors>({});
    31	  const [notice, setNotice] = useState<Notice | null>(null);
    32	  const [createProperty, { loading }] = useMutation(CreatePropertyMutation);
    33	
    34	  const update = (field: keyof PropertyFormValues) => (value: string) => {
    35	    setValues((current) => ({ ...current, [field]: value }));
    36	    setErrors((current) => ({ ...current, [field]: undefined }));
    37	  };
    38	
    39	  async function onSubmit(event: FormEvent<HTMLFormElement>) {
    40	    event.preventDefault();
    41	    setNotice(null);
    42	    const clientErrors = validateProperty(values);
    43	    setErrors(clientErrors);
    44	    if (Object.keys(clientErrors).length > 0) return;
    45	
    46	    try {
    47	      const { data } = await createProperty({
    48	        variables: { input: { ...values, state: values.state as USState } },
    49	      });
    50	      const result = data?.createProperty;
    51	      switch (result?.__typename) {
    52	        case 'CreatePropertySuccess':
    53	          await navigate(`/properties/${result.property.id}`);
    54	          return;
    55	        case 'InvalidInputError':
    56	          setErrors(
    57	            Object.fromEntries(result.fieldErrors.map(({ field, message }) => [field, message])),
    58	          );
    59	          return;
    60	        case 'DuplicatePropertyError':
    61	          setNotice({ kind: 'duplicate', ...result });
    62	          return;
    63	        case 'WeatherUnavailableError':
    64	          setNotice({ kind: 'weather', message: result.message });
    65	          return;
    66	        default:
    67	          setNotice({ kind: 'error', message: 'Unexpected response from the server.' });
    68	      }
    69	    } catch {
    70	      setNotice({ kind: 'error', message: 'Could not reach the server. Please try again.' });
    71	    }
    72	  }
    73	
    74	  return (
    75	    <form onSubmit={onSubmit} noValidate className="grid gap-5">
    76	      {notice && <NoticeAlert notice={notice} />}
    77	
    78	      <Field id="street" label="Street" error={errors.street}>
    79	        <Input
    80	          id="street"
    81	          value={values.street}
    82	          onChange={(e) => update('street')(e.target.value)}
    83	          placeholder="15528 E Golden Eagle Blvd"
    84	          aria-invalid={!!errors.street}
    85	          aria-describedby={errors.street ? 'street-error' : undefined}
    86	        />
    87	      </Field>
    88	
    89	      <Field id="city" label="City" error={errors.city}>
    90	        <Input
    91	          id="city"
    92	          value={values.city}
    93	          onChange={(e) => update('city')(e.target.value)}
    94	          placeholder="Fountain Hills"
    95	          aria-invalid={!!errors.city}
    96	          aria-describedby={errors.city ? 'city-error' : undefined}
    97	        />
    98	      </Field>
    99	
   100	      <div className="grid grid-cols-2 items-start gap-4">
   101	        <Field id="state" label="State" error={errors.state}>
   102	          <NativeSelect
   103	            id="state"
   104	            value={values.state}
   105	            onChange={(e) => update('state')(e.target.value)}
   106	            aria-invalid={!!errors.state}
   107	            aria-describedby={errors.state ? 'state-error' : undefined}
   108	            className="w-full"
   109	          >
   110	            <NativeSelectOption value="">Select…</NativeSelectOption>
   111	            {STATES.map((state) => (
   112	              <NativeSelectOption key={state} value={state}>
   113	                {state}
   114	              </NativeSelectOption>
   115	            ))}
   116	          </NativeSelect>
   117	        </Field>
   118	
   119	        <Field id="zipCode" label="Zip code" error={errors.zipCode}>
   120	          <Input
   121	            id="zipCode"
   122	            value={values.zipCode}
   123	            onChange={(e) => update('zipCode')(e.target.value)}
   124	            placeholder="85268"
   125	            inputMode="numeric"
   126	            maxLength={5}
   127	            aria-invalid={!!errors.zipCode}
   128	            aria-describedby={errors.zipCode ? 'zipCode-error' : undefined}
   129	          />
   130	        </Field>
   131	      </div>
   132	
   133	      <Button type="submit" disabled={loading} className="justify-self-start">
   134	        {loading ? 'Creating…' : 'Create property'}
   135	      </Button>
   136	    </form>
   137	  );
   138	}
   139	
   140	function Field({
   141	  id,
   142	  label,
   143	  error,
   144	  children,
   145	}: {
   146	  id: string;
   147	  label: string;
   148	  error: string | undefined;
   149	  children: React.ReactNode;
   150	}) {
   151	  return (
   152	    <div className="grid gap-2">
   153	      <Label htmlFor={id}>{label}</Label>
   154	      {children}
   155	      {error && (
   156	        <p id={`${id}-error`} className="text-sm text-destructive">
   157	          {error}
   158	        </p>
   159	      )}
   160	    </div>
   161	  );
   162	}
   163	
   164	function NoticeAlert({ notice }: { notice: Notice }) {
   165	  if (notice.kind === 'weather') {
   166	    return (
   167	      <Alert variant="destructive">
   168	        <CloudOff />
   169	        <AlertTitle>Weather data unavailable, property not created</AlertTitle>
   170	        <AlertDescription>{notice.message}</AlertDescription>
   171	      </Alert>
   172	    );
   173	  }
   174	  if (notice.kind === 'duplicate') {
   175	    return (
   176	      <Alert>
   177	        <AlertTitle>{notice.message}</AlertTitle>
