 4	/** A persisted property as the rest of the app sees it (SPEC S7). */
 5	export type PropertyRecord = Property;
 6	export type { USState };
 7	
 8	/** The address that identifies a property; duplicates are exact matches on all four (S5.4). */
 9	export interface Address {
10	  street: string;
11	  city: string;
12	  state: USState;
13	  zipCode: string;
14	}
15	
16	export interface NewProperty extends Address {
17	  weatherData: Record<string, unknown>;
18	  lat: number;
19	  long: number;
20	}
21	
22	export type InsertResult =
23	  { ok: true; property: PropertyRecord } | { ok: false; duplicateOf: string };
24	
25	export type SortDirection = 'asc' | 'desc';
26	
27	/** Already validated and normalized by the service; absent fields apply no constraint. */
28	export interface PropertyFilter {
29	  city?: string;
30	  zipCode?: string;
31	  state?: USState;
32	}
33	
34	export interface ListOptions {
35	  direction: SortDirection;
36	  filter?: PropertyFilter;
37	}
38	
39	export interface PropertyRepository {
40	  /** Properties by creation time, ties broken by id in the same direction (S2.3). */
41	  list(options: ListOptions): Promise<PropertyRecord[]>;
42	  findByAddress(address: Address): Promise<PropertyRecord | null>;
43	  /** Inserts, or reports the existing row when the address unique key is already taken. */
44	  insert(data: NewProperty): Promise<InsertResult>;
45	}
46	
47	const UNIQUE_VIOLATION = 'P2002';
48	
49	/**
50	 * Prisma's `contains` passes the value into ILIKE unescaped, so `%` and `_` would act as
51	 * wildcards. Escape them (and the escape character itself) to match literally (S3.3).
52	 */
53	const escapeLike = (value: string) => value.replace(/[\\%_]/g, (char) => `\\${char}`);
54	
55	export function createPropertyRepository(prisma: PrismaClient): PropertyRepository {
56	  const findByAddress = ({ street, city, state, zipCode }: Address) =>
57	    prisma.property.findUnique({
58	      where: { street_city_state_zipCode: { street, city, state, zipCode } },
59	    });
60	
61	  return {
62	    list: ({ direction, filter = {} }) =>
63	      prisma.property.findMany({
64	        where: {
65	          // S3.2 case-insensitive substring.
66	          ...(filter.city && { city: { contains: escapeLike(filter.city), mode: 'insensitive' } }),
67	          ...(filter.zipCode && { zipCode: filter.zipCode }),
68	          ...(filter.state && { state: filter.state }),
69	        },
70	        orderBy: [{ createdAt: direction }, { id: direction }],
71	      }),
72	
73	    findByAddress,
74	
75	    async insert({ weatherData, ...fields }) {
76	      try {
77	        const property = await prisma.property.create({
78	          data: { ...fields, weatherData: weatherData as Prisma.InputJsonObject },
79	        });
80	        return { ok: true, property };
81	      } catch (error) {
82	        if (
83	          error instanceof Prisma.PrismaClientKnownRequestError &&
84	          error.code === UNIQUE_VIOLATION
85	        ) {
86	          // Lost a race with a concurrent create of the same address (S5.4).
87	          const existing = await findByAddress(fields);
88	          if (existing) return { ok: false, duplicateOf: existing.id };
89	        }
90	        throw error;
91	      }
92	    },
93	  };
94	}
