/** Loads the repo-root `.env` if present. Variables already set in the environment win. */
export function loadRootEnv(): void {
  try {
    process.loadEnvFile(new URL('../../../.env', import.meta.url));
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error;
  }
}
import { z } from 'zod';
import { loadRootEnv } from './load-env.ts';

const Env = z.object({
  DATABASE_URL: z.url(),
  // Free tier is HTTP-only (SPEC open questions), so the base URL is configurable.
  WEATHERSTACK_BASE_URL: z.url().default('http://api.weatherstack.com'),
  WEATHERSTACK_ACCESS_KEY: z.string().min(1),
  PORT: z.coerce.number().int().positive().default(4000),
});

export type Env = z.infer<typeof Env>;

export function readEnv(source: NodeJS.ProcessEnv = process.env): Env {
  // Only the real process env is backed by the repo-root .env; explicit sources (tests) stay pure.
  if (source === process.env) loadRootEnv();
  const parsed = Env.safeParse(source);
  if (!parsed.success) {
    // Report variable names only; values may be secrets (SPEC S5.2).
    const names = parsed.error.issues.map((issue) => issue.path.join('.')).join(', ');
    throw new Error(`Invalid or missing environment variables: ${names}. See .env.example.`);
  }
  return parsed.data;
}
import { createServer } from 'node:http';
import { createApp } from './app.ts';
import { createServices } from './container.ts';
import { createPrismaClient } from './db.ts';
import { readEnv } from './env.ts';

const env = readEnv();
const prisma = createPrismaClient(env.DATABASE_URL);
const app = createApp({ services: createServices(env, prisma) });
const server = createServer(app);

server.listen(env.PORT, () => {
  console.info(`GraphQL API on http://localhost:${env.PORT}${app.graphqlEndpoint}`);
});

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.once(signal, () => {
    server.close();
    void prisma.$disconnect();
  });
}
/** postgres-test from docker-compose.yml; never the dev database (CLAUDE.md "Tests"). */
export const TEST_DATABASE_URL =
  process.env['TEST_DATABASE_URL'] ??
  'postgresql://[REDACTED]@localhost:5433/covertree_test';
import { execFileSync } from 'node:child_process';
import { TEST_DATABASE_URL } from './test-database-url.ts';

/** Applies pending migrations to postgres-test once per integration run (never drops data). */
export function setup(): void {
  const url = TEST_DATABASE_URL;
  if (!url.includes(':5433/')) throw new Error(`Refusing to migrate a non-test database: ${url}`);
  execFileSync('pnpm', ['exec', 'prisma', 'migrate', 'deploy'], {
    env: { ...process.env, DATABASE_URL: url },
    stdio: 'inherit',
  });
}
import { defineConfig } from 'prisma/config';
import { loadRootEnv } from './src/load-env.ts';

loadRootEnv();

export default defineConfig({
  schema: 'prisma/schema.prisma',
  migrations: { path: 'prisma/migrations' },
  // Undefined is fine for `prisma generate`; migrate commands fail with a clear message.
  datasource: { url: process.env['DATABASE_URL'] },
});
